self._T.keyCodeByName = {} self._T.keyNameByCode = {} self._T.displayByName = {}
-- 왼쪽 값은 KeyboardKey 열거형의 멤버 이름입니다. Maker의 열거형 -- 목록과 이름이 다르면 RegisterKey가 조용히 건너뛰고 로그를 남기니, -- 실행 후 로그에 "not found"가 찍히는 항목만 이름을 고쳐주세요. self:RegisterKey("LeftArrow", "Left", "←") self:RegisterKey("RightArrow", "Right", "→") self:RegisterKey("UpArrow", "Up", "↑") self:RegisterKey("DownArrow", "Down", "↓") self:RegisterKey("Space", "Space", "Space") self:RegisterKey("Enter", "Enter", "Enter") self:RegisterKey("Escape", "Escape", "Esc") self:RegisterKey("LeftShift", "Shift", "Shift") self:RegisterKey("LeftControl", "Ctrl", "Ctrl")
for i = 0, 25 do local letter = string.char(65 + i) self:RegisterKey(letter, letter, letter) end for i = 0, 9 do local digit = tostring(i) self:RegisterKey("Alpha" .. digit, digit, digit) end
